"""Explain allocation order, pointer markers and loop cleanup branches."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1809': ('종이 두 장 묶음을 빌리는 일과 그중 한 장을 게시판에 연결하는 일은 크기가 다를 수 있어요. 할당량과 연결 범위를 따로 세어 봐요.', 'order로 정한 할당량과 한 번의 mapping 길이를 구별합니다.', '페이지가 4096바이트일 때 할당 묶음 8192와 연결 범위 4096을 따로 적으세요.', ['ioremap 검사 hook는 데이터에 대응하는 shadow 준비표와 origin 원인표를 새로 마련해요. alloc_pages는 페이지 메모리를 요청하는 함수이고 mapping은 가상 주소로 그 페이지에 접근할 수 있게 연결하는 작업이에요.', '반복문 안의 두 할당은 모두 alloc_pages(gfp_mask, 1)이에요. 마지막 인자는 페이지 개수가 아니라 order예요. 페이지 수는 2의 order승이므로 order 1은 두 페이지 묶음을 뜻해요.', '페이지가 4096바이트라면 shadow용 요청은 8192바이트 묶음이고 origin용 요청도 8192바이트 묶음이에요. 둘은 따로 부르는 할당이에요. 실제 확보 성공 여부는 뒤의 NULL 검사로 확인해요.', 'gfp_mask는 GFP_KERNEL과 __GFP_ZERO를 합친 요청 조건이에요. ZERO는 0으로 채운 메모리를 요청하는 표시예요. 이 조건은 새 검사표를 준비할 때 사용하는 것이며 원래 장치 데이터를 0으로 지우라는 뜻이 아니에요.', '각 연결 호출은 start + off부터 start + off + PAGE_SIZE에 대응하는 가상 범위를 사용해요. 한 번의 연결 범위 길이는 PAGE_SIZE예요. 그러므로 할당 order가 1이라는 이유로 연결 길이도 반드시 두 페이지라고 읽으면 안 돼요.', '이 수업은 고정 코드에 실제로 적힌 두 크기를 비교해요. 차이가 있다고 소스를 임의로 order 0이라고 설명하거나 나머지 페이지의 수명이 자동으로 증명됐다고 생각하지 마세요. 자원 정리와 실제 할당자의 동작은 별도로 추적해야 해요.'], [('이 원문의 shadow와 origin 할당에 전달하는 order는 무엇인가요?', ['0이에요', '1이에요'], '정답은 두 번째예요. 두 alloc_pages 호출의 마지막 인자가 1이에요. order 1은 한 페이지가 아니라 두 페이지 묶음이라는 점도 기억하세요.'), ('한 번의 metadata 연결 호출이 지정하는 가상 범위 길이는 얼마인가요?', ['PAGE_SIZE예요', '언제나 2 × PAGE_SIZE예요'], '정답은 첫 번째예요. 시작에 PAGE_SIZE를 더한 주소가 끝이에요. 할당량과 연결할 가상 범위의 길이는 별도로 읽어야 해요.')]), 'os1810': ('물건을 선반에 연결해 놓은 뒤 손에 들고 있던 위치 쪽지를 비울 수 있어요. 쪽지를 비운다고 물건 자체가 사라지는 것은 아니에요.', '연결 성공 뒤 지역 포인터의 NULL 표시를 이해합니다.', 'shadow 할당 → 연결 성공 → shadow=NULL을 쓰고, 페이지와 연결은 남아 있다고 따로 표시하세요.', ['이 함수는 shadow와 origin 페이지를 새로 할당한 뒤 각각 가상 주소에 연결해요. 지역 변수 shadow와 origin은 이번 반복에서 준비한 페이지를 가리키는 포인터예요. NULL은 그 지역 변수가 더 이상 페이지 주소를 담지 않는다는 표시예요.', '먼저 shadow 연결을 요청하고 반환값 mapped를 확인해요. 이 API에서 0은 성공이고 0이 아니면 오류예요. 변수 이름만 보고 연결한 페이지 개수라고 생각하지 마세요.', 'shadow 연결이 성공하면 shadow = NULL을 실행해요. 이어 origin을 연결하고 그것도 성공하면 origin = NULL로 바꿔요. 대입 뒤에도 가상 주소와 페이지의 연결이 저절로 없어지는 것은 아니에요.', '뒤의 정리 블록은 if (shadow), if (origin)으로 남아 있는 지역 포인터를 보고 free 여부를 정해요. 그래서 성공 뒤 NULL로 비운 표시와 아직 성공하지 않은 자원의 주소를 구별할 수 있어요. 실제 반납은 __free_pages 같은 함수 호출이 맡아요.', '예를 들어 shadow 연결만 성공한 시점에는 지역 shadow는 NULL이고 origin에는 아직 페이지 주소가 있어요. 두 연결이 모두 성공하면 둘 다 NULL이에요. 두 포인터가 NULL이어도 두 자원을 할당한 사실과 성공한 연결은 남아 있어요.', '이 표시 방식만 보고 실패 복구가 완벽하다고 단정하면 안 돼요. 정리 블록을 실행할 조건과 이미 연결한 범위의 해제도 따로 확인해야 해요. 다음 수업에서는 clean 값에 따라 어떤 정리를 건너뛰는지 살펴봐요.'], [('연결 성공 뒤 shadow = NULL을 실행하면 페이지가 즉시 반납되나요?', ['네. NULL 대입 자체가 free를 실행해요', '아니요. 지역 포인터 값만 바뀌어요'], '정답은 두 번째예요. 대입은 해당 변수의 값을 비우는 동작이에요. 연결 해제와 페이지 반납은 별도 함수가 담당해요.'), ('이 hook가 부르는 연결 함수의 결과 0은 무엇을 뜻하나요?', ['성공이에요', '반드시 오류예요'], '정답은 첫 번째예요. if (mapped)는 0이 아닌 결과를 오류로 처리해요. 성공 뒤에야 NULL 대입으로 진행해요.')]), 'os1811': ('한 바퀴를 다 돈 뒤에만 완료 도장을 찍는다고 생각해 보세요. 첫 바퀴 중간에 출구로 나가면 완료 숫자는 아직 0이에요.', 'for 갱신식과 goto가 clean 값에 주는 영향을 이해합니다.', '첫 반복 시작의 i=0, clean=0을 적고 실패 → goto ret 경로가 갱신식을 건너뛰는지 확인하세요.', ['clean은 이 함수의 정리 범위를 결정하는 숫자예요. 처음에는 0으로 시작해요. 이름이 clean이라고 해서 오류를 만나면 모든 자원이 자동으로 정리되는 것은 아니에요. 이 값을 사용하는 조건문을 봐야 해요.', 'for문의 갱신식은 i++, off += PAGE_SIZE, clean = i예요. 본문을 정상적으로 마친 뒤 i를 먼저 늘리고 off를 늘린 다음 늘어난 i를 clean에 넣어요. 첫 반복을 끝내면 i=1, clean=1이 돼요.', '하지만 첫 반복의 할당이나 연결 단계에서 goto ret를 만나면 곧바로 ret로 이동해요. for문의 끝 갱신식은 실행하지 않아요. 그러므로 이 경로에서 clean은 여전히 0이에요.', 'ret의 주요 정리 블록은 if (clean > 0) 안에 있어요. clean=0이면 이 블록의 페이지 반납과 이전 범위 연결 해제는 건너뛰어요. 실패했다는 사실만으로 이 조건이 자동으로 참이 되지는 않아요.', '예를 들어 첫 shadow 할당은 성공하고 첫 origin 할당이 실패했다면, 성공한 shadow가 있어도 clean은 0이에요. 이 ret 블록의 free는 실행되지 않아요. origin 연결 실패의 경우에는 ret로 가기 전 shadow 연결 해제 호출이 따로 있으므로 실패 위치별로 읽어야 해요.', 'ret 아래의 캐시 처리와 leave_runtime은 clean 조건 밖에 있어요. 따라서 정상적으로 그 지점까지 진행하면 그것들은 실행돼요. runtime 복구와 페이지 반납을 구별하세요. 이 설명은 고정 코드의 분기 관찰이며 실제 커널 누수 실험을 수행했다는 뜻은 아니에요.'], [('첫 반복 도중 실패해 goto ret로 이동하면 clean은 얼마인가요?', ['이미 반복을 시작했으므로 1이에요', '갱신식에 도달하지 않았으므로 0이에요'], '정답은 두 번째예요. 시작과 완료는 달라요. clean = i는 반복 끝의 갱신식이므로 중간 goto에서는 실행하지 않아요.'), ('clean이 0이면 ret의 clean > 0 안에 있는 free 블록을 실행하나요?', ['아니요. 조건이 거짓이라 건너뛰어요', '네. 오류가 났으니 모든 정리 코드를 실행해요'], '정답은 첫 번째예요. 오류 처리 위치에도 조건문이 있어요. goto로 도착했다는 사실과 그 안의 조건이 참이라는 사실을 구별하세요.')]), 'os1812': ('어제 정리한 선반의 연결과 오늘 아직 손에 든 물건은 정리하는 방법이 달라요. 이전 반복의 연결과 현재 반복의 미완성 자원을 나눠 봐요.', '뒤쪽 실패에서 현재 자원 반납과 이전 연결 해제를 구별합니다.', '첫 반복 성공 뒤 두 번째 origin 할당 실패를 그리세요. 현재 shadow의 free와 이전 두 연결의 unmap을 따로 적으세요.', ['첫 반복이 정상적으로 끝나면 갱신식에서 clean이 1이 돼요. 두 번째 반복 도중 오류로 ret에 가면 clean > 0이 참이므로 주요 정리 블록을 실행해요. 첫 반복 실패와 다른 점이에요.', '블록은 현재 shadow 포인터가 있으면 __free_pages(shadow, 1)을 호출하고 origin도 같은 방식으로 확인해요. 성공한 연결 뒤 NULL로 바꾼 포인터는 이 개별 free 조건에 걸리지 않아요.', '이어서 처음부터 clean × PAGE_SIZE까지에 대응하는 shadow 연결과 origin 연결을 해제해요. clean은 앞에서 완료한 반복의 범위를 정하는 데 쓰여요. 현재 남은 지역 포인터와 이전에 만든 연결을 다른 방법으로 정리하는 구조예요.', '예를 들어 두 번째 반복의 shadow 할당은 성공하고 origin 할당은 실패했다면, 현재 shadow는 개별 free 대상이에요. origin은 NULL이에요. clean=1이므로 이전 한 페이지 구간의 shadow·origin 연결도 각각 해제해요.', 'unmap은 가상 주소와 페이지의 연결을 없애는 일이고 free는 할당한 페이지를 반납하는 일이에요. unmap 호출이 보인다는 이유만으로 이전의 모든 페이지 묶음까지 반납됐다고 결론 내리면 안 돼요. 실제 함수와 자원 소유 흐름을 더 따라가야 해요.', '모든 반복이 성공하면 코드가 clean=0으로 바꿔 정상 경로에서 오류 정리 블록을 건너뛰어요. 이때 0은 첫 실패의 0과 같은 숫자지만 앞서 수행한 작업은 달라요. 숫자뿐 아니라 그 숫자에 도달한 경로를 함께 확인하세요.'], [('뒤쪽 실패의 정리 블록은 어떤 두 대상을 나누어 처리하나요?', ['모든 포인터를 같은 자원 하나로 취급해요', '현재 지역 포인터의 자원과 이전 반복의 연결을 나누어요'], '정답은 두 번째예요. 현재 포인터는 조건부 free, 이전 범위는 unmap 호출로 다뤄요. NULL 표시와 clean 범위를 함께 읽어야 해요.'), ('unmap을 호출했다는 사실만으로 할당한 모든 페이지가 free됐다고 말할 수 있나요?', ['아니요. 연결 제거와 페이지 반납은 다른 동작이에요', '네. unmap과 free는 언제나 같은 함수예요'], '정답은 첫 번째예요. 가상 주소의 연결을 없애는 것과 메모리를 반납하는 책임은 구별해야 해요. 전체 복구 여부는 더 넓은 자원 흐름으로 확인해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_448.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
